package com.enterprise.procurement.persistence.mapper;
import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.enterprise.procurement.persistence.entity.PurchaseRequestEntity; import org.apache.ibatis.annotations.*; import java.util.*;
@Mapper public interface PurchaseRequestMapper extends BaseMapper<PurchaseRequestEntity> { @Update("UPDATE purchase_request SET status=#{toStatus}, version=version+1, updated_at=NOW() WHERE id=#{id} AND status=#{fromStatus} AND version=#{version}") int transition(@Param("id") Long id,@Param("fromStatus") String from,@Param("toStatus") String to,@Param("version") Integer version); @Select("SELECT * FROM purchase_request WHERE applicant_id=#{userId} ORDER BY created_at DESC") List<PurchaseRequestEntity> byApplicant(@Param("userId") Long userId); }
